# 分组：n 条记录按每组 size 条分组，返回组数。


def groups_of(n, size):
    return n // size + 1

verification_tests:
from target import groups_of


def test_empty_input_needs_no_group():
    assert groups_of(0, 5) == 0


def test_remainder_case():
    assert groups_of(11, 5) == 3


def test_exact_multiple():
    assert groups_of(10, 5) == 2
